                                                |qt_rt_const_q4[REM_WIDTH+1:0] 
                                               |qt_rt_const_q16[REM_WIDTH+1:0];
assign qt_rt_const_q24[REM_WIDTH+1:0]         =  qt_rt_const_q8[REM_WIDTH+1:0]   
