assign qt_rt_const_q44[REM_WIDTH+1:0]         =  qt_rt_const_q4[REM_WIDTH+1:0]
                                                |qt_rt_const_q8[REM_WIDTH+1:0]   
                                               |qt_rt_const_q32[REM_WIDTH+1:0]; 
assign qt_rt_const_q56[REM_WIDTH+1:0]         =  qt_rt_const_q8[REM_WIDTH+1:0]
