assign sqrt_rem_add5_op1_0[REM_WIDTH-1:0]      = rem_sign 
                                                ? sqrt_qt_r5_rem_add_op1_0[REM_WIDTH-1:0]
                                                : sqrt_qt_5_rem_add_op1_0[REM_WIDTH-1:0];
assign sqrt_rem_add5_op1_1[REM_WIDTH-1:0]      = rem_sign 
