module openhw_fpnew_opgroup_block #(
  parameter openhw_fpnew_pkg::opgroup_e        OpGroup       = openhw_fpnew_pkg::ADDMUL,
  // FPU configuration
  parameter int unsigned                Width         = 32,
  parameter logic                       EnableVectors = 1'b1,
  parameter openhw_fpnew_pkg::divsqrt_unit_t   DivSqrtSel    = openhw_fpnew_pkg::THMULTI,
  parameter openhw_fpnew_pkg::fmt_logic_t      FpFmtMask     = '1,
  parameter openhw_fpnew_pkg::ifmt_logic_t     IntFmtMask    = '1,
  parameter openhw_fpnew_pkg::fmt_unsigned_t   FmtPipeRegs   = '{default: 0},
  parameter openhw_fpnew_pkg::fmt_unit_types_t FmtUnitTypes  = '{default: openhw_fpnew_pkg::PARALLEL},
  parameter openhw_fpnew_pkg::pipe_config_t    PipeConfig    = openhw_fpnew_pkg::BEFORE,
  parameter type                        TagType       = logic,
  parameter int unsigned                TrueSIMDClass = 0,
  // Do not change
  localparam int unsigned NUM_FORMATS  = openhw_fpnew_pkg::NUM_FP_FORMATS,
  localparam int unsigned NUM_OPERANDS = openhw_fpnew_pkg::num_operands(OpGroup),
  localparam int unsigned NUM_LANES    = openhw_fpnew_pkg::max_num_lanes(Width, FpFmtMask, EnableVectors),
  localparam type         MaskType     = logic [NUM_LANES-1:0]
) (
  input logic                                     clk_i,
  input logic                                     rst_ni,
  // Input signals
  input logic [NUM_OPERANDS-1:0][Width-1:0]       operands_i,
  input logic [NUM_FORMATS-1:0][NUM_OPERANDS-1:0] is_boxed_i,
  input openhw_fpnew_pkg::roundmode_e                    rnd_mode_i,
  input openhw_fpnew_pkg::operation_e                    op_i,
  input logic                                     op_mod_i,
  input openhw_fpnew_pkg::fp_format_e                    src_fmt_i,
  input openhw_fpnew_pkg::fp_format_e                    dst_fmt_i,
  input openhw_fpnew_pkg::int_format_e                   int_fmt_i,
  input logic                                     vectorial_op_i,
  input TagType                                   tag_i,
  input MaskType                                  simd_mask_i,
  // Input Handshake
  input  logic                                    in_valid_i,
  output logic                                    in_ready_o,
  input  logic                                    flush_i,
  // Output signals
  output logic [Width-1:0]                        result_o,
  output openhw_fpnew_pkg::status_t                      status_o,
  output logic                                    extension_bit_o,
  output TagType                                  tag_o,
  // Output handshake
  output logic                                    out_valid_o,
  input  logic                                    out_ready_i,
  // Indication of valid data in flight
  output logic                                    busy_o,
  output logic                                    early_valid_o
);

  // ----------------
  // Type Definition
  // ----------------
  typedef struct packed {
    logic [Width-1:0]   result;
    openhw_fpnew_pkg::status_t status;
    logic               ext_bit;
    TagType             tag;
  } output_t;

  // Handshake signals for the slices
  logic [NUM_FORMATS-1:0] fmt_in_ready, fmt_out_valid, fmt_out_ready, fmt_busy;
  logic [NUM_FORMATS-1:0] early_valid;
  output_t [NUM_FORMATS-1:0] fmt_outputs;

  // -----------
  // Input Side
  // -----------
  assign in_ready_o = in_valid_i & fmt_in_ready[dst_fmt_i]; // Ready is given by selected format

  // -------------------------
  // Generate Parallel Slices
  // -------------------------
  for (genvar fmt = 0; fmt < int'(NUM_FORMATS); fmt++) begin : gen_parallel_slices
    // Some constants for this format
    localparam logic ANY_MERGED = openhw_fpnew_pkg::any_enabled_multi(FmtUnitTypes, FpFmtMask);
    localparam logic IS_FIRST_MERGED =
        openhw_fpnew_pkg::is_first_enabled_multi(openhw_fpnew_pkg::fp_format_e'(fmt), FmtUnitTypes, FpFmtMask);

    // Generate slice only if format enabled
    if (FpFmtMask[fmt] && (FmtUnitTypes[fmt] == openhw_fpnew_pkg::PARALLEL)) begin : active_format
      localparam openhw_fpnew_pkg::fp_format_e FpFormat = openhw_fpnew_pkg::fp_format_e'(fmt);

      logic in_valid;

      assign in_valid = in_valid_i & (dst_fmt_i == openhw_fpnew_pkg::fp_format_e'(fmt)); // enable selected format

      // Forward masks related to the right SIMD lane
      localparam int unsigned INTERNAL_LANES = openhw_fpnew_pkg::num_lanes(Width, openhw_fpnew_pkg::fp_format_e'(fmt), EnableVectors);
      logic [INTERNAL_LANES-1:0] mask_slice;
      always_comb for (int b = 0; b < INTERNAL_LANES; b++) mask_slice[b] = simd_mask_i[(NUM_LANES/INTERNAL_LANES)*b];

      openhw_fpnew_opgroup_fmt_slice #(
        .OpGroup       ( OpGroup          ),
        .FpFormat      ( FpFormat         ),
        .Width         ( Width            ),
        .EnableVectors ( EnableVectors    ),
        .NumPipeRegs   ( FmtPipeRegs[fmt] ),
        .PipeConfig    ( PipeConfig       ),
        .TagType       ( TagType          ),
        .TrueSIMDClass ( TrueSIMDClass    )
      ) i_fmt_slice (
        .clk_i,
        .rst_ni,
        .operands_i       ( operands_i               ),
        .is_boxed_i       ( is_boxed_i[fmt]          ),
        .rnd_mode_i,
        .op_i,
        .op_mod_i,
        .vectorial_op_i,
        .tag_i,
        .simd_mask_i      ( mask_slice               ),
        .in_valid_i       ( in_valid                 ),
        .in_ready_o       ( fmt_in_ready[fmt]        ),
        .flush_i,
        .result_o         ( fmt_outputs[fmt].result  ),
        .status_o         ( fmt_outputs[fmt].status  ),
        .extension_bit_o  ( fmt_outputs[fmt].ext_bit ),
        .tag_o            ( fmt_outputs[fmt].tag     ),
        .out_valid_o      ( fmt_out_valid[fmt]       ),
        .out_ready_i      ( fmt_out_ready[fmt]       ),
        .busy_o           ( fmt_busy[fmt]            ),
        .reg_ena_i        ( '0                       ),
        .early_out_valid_o( early_valid[fmt]         )
      );
    // If the format wants to use merged ops, tie off the dangling ones not used here
    end else if (FpFmtMask[fmt] && ANY_MERGED && !IS_FIRST_MERGED) begin : merged_unused

      localparam FMT = openhw_fpnew_pkg::get_first_enabled_multi(FmtUnitTypes, FpFmtMask);
      // Ready is split up into formats
      assign fmt_in_ready[fmt]  = fmt_in_ready[int'(FMT)];

      assign fmt_out_valid[fmt] = 1'b0; // don't emit values
      assign fmt_busy[fmt]      = 1'b0; // never busy
      // Outputs are don't care
      assign fmt_outputs[fmt].result  = '{default: openhw_fpnew_pkg::DONT_CARE};
      assign fmt_outputs[fmt].status  = '{default: openhw_fpnew_pkg::DONT_CARE};
      assign fmt_outputs[fmt].ext_bit = openhw_fpnew_pkg::DONT_CARE;
      assign fmt_outputs[fmt].tag     = TagType'(openhw_fpnew_pkg::DONT_CARE);
      assign early_valid[fmt] = 1'b0;
    // Tie off disabled formats
    end else if (!FpFmtMask[fmt] || (FmtUnitTypes[fmt] == openhw_fpnew_pkg::DISABLED)) begin : disable_fmt
      assign fmt_in_ready[fmt]  = 1'b0; // don't accept operations
      assign fmt_out_valid[fmt] = 1'b0; // don't emit values
      assign fmt_busy[fmt]      = 1'b0; // never busy
      // Outputs are don't care
      assign fmt_outputs[fmt].result  = '{default: openhw_fpnew_pkg::DONT_CARE};
      assign fmt_outputs[fmt].status  = '{default: openhw_fpnew_pkg::DONT_CARE};
      assign fmt_outputs[fmt].ext_bit = openhw_fpnew_pkg::DONT_CARE;
      assign fmt_outputs[fmt].tag     = TagType'(openhw_fpnew_pkg::DONT_CARE);
      assign early_valid[fmt] = 1'b0;
    end
  end

  // ----------------------
  // Generate Merged Slice
  // ----------------------
  if (openhw_fpnew_pkg::any_enabled_multi(FmtUnitTypes, FpFmtMask)) begin : gen_merged_slice

    localparam FMT = openhw_fpnew_pkg::get_first_enabled_multi(FmtUnitTypes, FpFmtMask);
    localparam REG = openhw_fpnew_pkg::get_num_regs_multi(FmtPipeRegs, FmtUnitTypes, FpFmtMask);

    logic in_valid;

    assign in_valid = in_valid_i & (FmtUnitTypes[dst_fmt_i] == openhw_fpnew_pkg::MERGED);

    openhw_fpnew_opgroup_multifmt_slice #(
      .OpGroup       ( OpGroup          ),
      .Width         ( Width            ),
      .FpFmtConfig   ( FpFmtMask        ),
      .IntFmtConfig  ( IntFmtMask       ),
      .EnableVectors ( EnableVectors    ),
      .DivSqrtSel    ( DivSqrtSel       ),
      .NumPipeRegs   ( REG              ),
      .PipeConfig    ( PipeConfig       ),
      .TagType       ( TagType          )
    ) i_multifmt_slice (
      .clk_i,
      .rst_ni,
      .operands_i,
      .is_boxed_i,
      .rnd_mode_i,
      .op_i,
      .op_mod_i,
      .src_fmt_i,
      .dst_fmt_i,
      .int_fmt_i,
      .vectorial_op_i,
      .tag_i,
      .simd_mask_i      ( simd_mask_i              ),
      .in_valid_i       ( in_valid                 ),
      .in_ready_o       ( fmt_in_ready[FMT]        ),
      .flush_i,
      .result_o         ( fmt_outputs[FMT].result  ),
      .status_o         ( fmt_outputs[FMT].status  ),
      .extension_bit_o  ( fmt_outputs[FMT].ext_bit ),
      .tag_o            ( fmt_outputs[FMT].tag     ),
      .out_valid_o      ( fmt_out_valid[FMT]       ),
      .out_ready_i      ( fmt_out_ready[FMT]       ),
      .busy_o           ( fmt_busy[FMT]            ),
      .reg_ena_i        ( '0                       ),
      .early_out_valid_o( early_valid[FMT]         )
    );

  end

  // ------------------
  // Arbitrate Outputs
  // ------------------
  output_t arbiter_output;

  // Round-Robin arbiter to decide which result to use
  openhw_rr_arb_tree #(
    .NumIn     ( NUM_FORMATS ),
    .DataType  ( output_t    ),
    .AxiVldRdy ( 1'b1        )
  ) i_arbiter (
    .clk_i,
    .rst_ni,
    .flush_i,
    .rr_i   ( '0             ),
    .req_i  ( fmt_out_valid  ),
    .gnt_o  ( fmt_out_ready  ),
    .data_i ( fmt_outputs    ),
    .gnt_i  ( out_ready_i    ),
    .req_o  ( out_valid_o    ),
    .data_o ( arbiter_output ),
    .idx_o  ( /* unused */   )
  );

  // Unpack output
  assign result_o        = arbiter_output.result;
  assign status_o        = arbiter_output.status;
  assign extension_bit_o = arbiter_output.ext_bit;
  assign tag_o           = arbiter_output.tag;

  assign early_valid_o   = |early_valid;

  assign busy_o = (| fmt_busy);

endmodule
